# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Api::V1::Invoices::BulkDeletion#create billing fence", type: :request do
  let(:company) { create(:company) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:client) { create(:client, company:) }

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
  end

  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  # Today each destroy commits on its own, so a fence checked per invoice could delete some and refuse the rest.
  it "refuses a whole bulk deletion during a handoff and removes no invoice or line item" do
    invoices = create_list(:invoice, 3, company:, client:)
    invoices.each { |invoice| create(:invoice_line_item, invoice:) }
    invoice_ids = invoices.map(&:id)
    line_item_ids = InvoiceLineItem.where(invoice_id: invoice_ids).pluck(:id)
    expect(line_item_ids.size).to eq(3)

    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    send_request :post, api_v1_invoices_bulk_deletion_index_path,
      params: { invoices_ids: invoice_ids },
      headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(Invoice.where(id: invoice_ids).count).to eq(3)
    expect(InvoiceLineItem.where(id: line_item_ids).count).to eq(3)
  end
end

RSpec.describe "Api::V1::Invoices::BulkDeletion#create mixed batch inside the fence", type: :request do
  let(:company) { create(:company) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:client) { create(:client, company:) }

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
  end

  # "With no handoff the behaviour is unchanged."
  # Inside one shared fence transaction, a refused destroy must still roll back the line items it removed
  # before the payment check refused it.
  it "keeps a paid invoice and its line items whole when a mixed bulk deletion runs with no handoff" do
    deletable = create(:invoice, company:, client:)
    with_payment = create(:invoice, company:, client:, amount_due: 300)
    line_item = create(:invoice_line_item, invoice: with_payment)
    create(:payment, invoice: with_payment, amount: 300)
    money_before = with_payment.reload.attributes.slice("amount", "tax", "discount", "outstanding_amount")

    send_request :post, api_v1_invoices_bulk_deletion_index_path,
      params: { invoices_ids: [deletable.id, with_payment.id] },
      headers: auth_headers(user)

    expect(response).to have_http_status(:unprocessable_content)
    expect(json_response["undeletable_invoice_ids"]).to eq([with_payment.id])
    expect(Invoice.exists?(deletable.id)).to be(false)
    expect(InvoiceLineItem.exists?(line_item.id)).to be(true)
    expect(with_payment.reload.attributes.slice("amount", "tax", "discount", "outstanding_amount")).to eq(money_before)
  end
end
